contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint v) public payable {
        require(v < type(uint).max);
        c.SetMinSum(v); if (__ESBMC_reverted()) return;
        uint before = c.MinSum(); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.SetMinSum(v + 1); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted && c.MinSum() == v && before == v);
    }
    receive() external payable {}
}

